/* ============================================================
 * search.js — Ctrl/Cmd+K command palette. Offline index in
 * window.BIOR_SEARCH_INDEX (generated by tools/build-search-index.mjs).
 * Chinese substring match; English token prefix match. Highlighting
 * operates on text nodes only (no HTML injection of query).
 * ============================================================ */
(function () {
  "use strict";
  var B = window.BIOR;
  var esc = B.escapeHtml;

  var GROUPS = [
    { type: "chapter", label: "章节" },
    { type: "cheatsheet", label: "速查" },
    { type: "special", label: "专栏" },
    { type: "term", label: "术语" },
    { type: "dataset", label: "数据集" }
  ];
  var ORDER = { chapter: 0, cheatsheet: 1, special: 2, term: 3, dataset: 4 };

  var root = null, input = null, results = null;
  var sel = 0, items = [];
  var recent = [];

  function rel() {
    return /\/chapters\/[^/]*$/.test(decodeURIComponent(location.pathname)) ? "../" : "";
  }

  function tokenize(q) {
    return q.toLowerCase().split(/\s+/).filter(Boolean);
  }

  function scoreRecord(rec, q, tokens) {
    var title = (rec.title || "").toLowerCase();
    var text = (rec.text || "").toLowerCase();
    var kws = (rec.keywords || []).join(" ").toLowerCase();
    var s = 0;
    if (title === q) s += 100;
    else if (title.indexOf(q) === 0) s += 60;
    else if (title.indexOf(q) !== -1) s += 40;
    if (kws && (tokens.some(function (t) { return kws.indexOf(t) !== -1; }) || kws.indexOf(q) !== -1)) s += 25;
    if (text.indexOf(q) !== -1) s += 12;
    tokens.forEach(function (t) {
      if (title.indexOf(t) !== -1) s += 30;
      else if (kws.indexOf(t) !== -1) s += 20;
      else if (text.indexOf(t) !== -1) s += 8;
    });
    if (!s) return -1;
    return s * 10 - (ORDER[rec.type] || 9);
  }

  function query(q) {
    var idx = window.BIOR_SEARCH_INDEX || [];
    var tokens = tokenize(q);
    if (!q.trim()) {
      // recent history
      return recent.slice(0, 5).map(function (r) {
        var rec = idx.filter(function (x) { return x.href === r.href && x.title === r.title; })[0];
        return rec ? { rec: rec, score: 0, hit: "" } : null;
      }).filter(Boolean);
    }
    var out = [];
    idx.forEach(function (rec) {
      var s = scoreRecord(rec, q.toLowerCase(), tokens);
      if (s > 0) out.push({ rec: rec, score: s });
    });
    out.sort(function (a, b) { return b.score - a.score; });
    // cap per group at 6
    var perGroup = {};
    out = out.filter(function (o) {
      perGroup[o.rec.type] = (perGroup[o.rec.type] || 0) + 1;
      return perGroup[o.rec.type] <= 6;
    });
    return out.slice(0, 24).map(function (o) {
      var text = o.rec.text || "";
      var at = text.toLowerCase().indexOf(q.toLowerCase());
      var hit = at === -1 ? text.slice(0, 80) : text.slice(Math.max(0, at - 14), at + 50);
      return { rec: o.rec, score: o.score, hit: hit };
    });
  }

  function highlight(text, q) {
    var holder = document.createElement("span");
    holder.textContent = text;
    if (!q) return holder;
    var low = text.toLowerCase(), ql = q.toLowerCase();
    var at = low.indexOf(ql);
    if (at === -1) return holder;
    var out = document.createElement("span");
    out.appendChild(document.createTextNode(text.slice(0, at)));
    var mark = document.createElement("mark");
    mark.className = "pi-hl";
    mark.textContent = text.slice(at, at + q.length);
    out.appendChild(mark);
    out.appendChild(document.createTextNode(text.slice(at + q.length)));
    return out;
  }

  function render() {
    var q = input.value.trim();
    var found = query(q);
    results.innerHTML = "";
    items = [];
    var lastType = null;
    found.forEach(function (o) {
      if (o.rec.type !== lastType) {
        lastType = o.rec.type;
        var g = GROUPS.filter(function (x) { return x.type === lastType; })[0];
        var gt = document.createElement("div");
        gt.className = "p-group-title";
        gt.textContent = g ? g.label : lastType;
        results.appendChild(gt);
      }
      var b = document.createElement("button");
      b.type = "button";
      b.className = "p-item";
      var t = document.createElement("span");
      t.className = "pi-t";
      t.appendChild(highlight(o.rec.title, q));
      var s = document.createElement("span");
      s.className = "pi-s";
      s.appendChild(highlight(o.hit, q));
      b.appendChild(t); b.appendChild(s);
      b.addEventListener("click", function () { open(o); });
      results.appendChild(b);
      items.push({ el: b, o: o });
    });
    if (!found.length) {
      var empty = document.createElement("div");
      empty.className = "p-empty";
      empty.innerHTML = "<p>没有找到「" + esc(q) + "」。</p>" +
        '<div class="p-suggest">' +
        ["t 检验", "热图", "join", "DESeq2", "箱线图", "NA"].map(function (s) {
          return '<button type="button" class="filter-chip" data-suggest="' + esc(s) + '">' + esc(s) + "</button>";
        }).join("") + "</div>";
      results.appendChild(empty);
      results.querySelectorAll("[data-suggest]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          input.value = btn.getAttribute("data-suggest");
          render();
          input.focus();
        });
      });
    }
    sel = 0;
    updateSel();
  }

  function updateSel() {
    items.forEach(function (it, i) { it.el.classList.toggle("sel", i === sel); });
    var cur = items[sel];
    if (cur) cur.el.scrollIntoView({ block: "nearest" });
  }

  function remember(o) {
    recent = recent.filter(function (r) { return !(r.href === o.rec.href && r.title === o.rec.title); });
    recent.unshift({ href: o.rec.href, title: o.rec.title });
    recent = recent.slice(0, 8);
    B.storage.set("bior.palette", recent);
  }

  function open(o) {
    remember(o);
    close();
    location.href = rel() + o.rec.href;
  }

  function show() {
    root.classList.add("open");
    try { recent = B.storage.get("bior.palette", []) || []; } catch (e) { recent = []; }
    input.value = "";
    render();
    input.focus();
  }
  function close() {
    root.classList.remove("open");
  }

  function build() {
    root = document.createElement("div");
    root.className = "palette-backdrop";
    root.innerHTML = '<div class="palette" role="dialog" aria-modal="true" aria-label="全站搜索">' +
      '<div class="palette-input-row">' + ICON_SVG + '<input class="palette-input" type="text" placeholder="搜索章节、报错、速查、术语…" aria-label="搜索关键词"></div>' +
      '<div class="palette-results" role="listbox"></div>' +
      '<div class="p-foot"><span>↑↓ 选择</span><span>Enter 打开</span><span>Esc 关闭</span><span style="margin-left:auto">离线索引</span></div>' +
      "</div>";
    document.body.appendChild(root);
    input = root.querySelector(".palette-input");
    results = root.querySelector(".palette-results");
    root.addEventListener("click", function (ev) {
      if (ev.target === root) close();
    });
    input.addEventListener("input", B.debounce(render, 120));
    input.addEventListener("keydown", function (ev) {
      if (ev.key === "ArrowDown") { ev.preventDefault(); sel = Math.min(items.length - 1, sel + 1); updateSel(); }
      else if (ev.key === "ArrowUp") { ev.preventDefault(); sel = Math.max(0, sel - 1); updateSel(); }
      else if (ev.key === "Enter") { ev.preventDefault(); if (items[sel]) open(items[sel].o); }
      else if (ev.key === "Escape") { close(); }
    });
  }

  var ICON_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.8-3.8"/></svg>';

  function init() {
    if (!window.BIOR_SEARCH_INDEX || !window.BIOR_SEARCH_INDEX.length) return;
    build();
    document.addEventListener("keydown", function (ev) {
      if ((ev.ctrlKey || ev.metaKey) && (ev.key === "k" || ev.key === "K")) {
        ev.preventDefault();
        if (root.classList.contains("open")) close(); else show();
      } else if (ev.key === "Escape" && root.classList.contains("open")) {
        close();
      }
    });
    document.querySelectorAll("[data-palette]").forEach(function (btn) {
      btn.addEventListener("click", show);
    });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
